function Edit-Block([string]$t,[string]$ph,[hashtable]$rules){
  $i=$t.IndexOf('${'+$ph+'}'); if($i -lt 0){throw "ph $ph not found"}
  $s=$t.LastIndexOf('<mc:AlternateContent>',$i)
  $e=$t.IndexOf('</mc:AlternateContent>',$i)+'</mc:AlternateContent>'.Length
  $blk=$t.Substring($s,$e-$s)
  foreach($k in $rules.Keys){
    $c=([regex]::Matches($blk,[regex]::Escape($k))).Count
    if($c -ne $rules[$k]){throw "$ph expected $($rules[$k]) of '$k' found $c"}
    $blk=$blk.Replace($k,$rules[$k+'_new'])
  }
  return $t.Remove($s,$e-$s).Insert($s,$blk)
}
