import com.zhishu.presale.permit.apply.doc.PresaleDocModel;
import com.zhishu.presale.permit.apply.doc.PresaleDocRenderEngine;

import java.io.ByteArrayOutputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;

/**
 * Bug 6315 独立验证 harness：
 * 1. 真引擎 PresaleDocRenderEngine.render 产出 PDF（bug6315-fixed.pdf，回写禅道用）；
 * 2. 以相同替换语义（range + shape 兜底）复制渲染为 Document，存 DOCX 检占位残留、存 PNG 供视觉核验。
 */
public class RenderBug6315 {
    public static void main(String[] args) throws Exception {
        Map<String, String> data = new HashMap<>();
        data.put("permitNo", "苏房预吴中 2026004 号");
        data.put("companyName", "测试开发企业_202610301124有限公司");
        data.put("creditCode", "91120104698909215X");
        data.put("projectName", "客测项目 11021033");
        data.put("projectAddress", "江苏省苏州市吴中区苏州大学附属尹山湖中学(尹安路南)");
        data.put("plannedUse", "住宅");
        data.put("saleScope", "2 号楼");
        data.put("totalArea", "690.36");
        data.put("areaDetail", "住宅 690.36㎡");
        data.put("houseCount", "6");
        data.put("houseDetail", "住宅 6 套");
        data.put("bankName", "中国工商银行股份有限公司北京怀柔支行");
        data.put("accountNo", "320211820261011098");
        data.put("remark", "预售有效期：2026-11-06 至 2028-11-06");
        data.put("issueYear", "2026");
        data.put("issueMonth", "11");
        data.put("issueDay", "6");

        PresaleDocModel model = new PresaleDocModel();
        for (Map.Entry<String, String> e : data.entrySet()) {
            model.put(e.getKey(), e.getValue());
        }

        // 1) 真引擎产物 PDF
        String tpl = "/templates/presale-permit-template.docx";
        byte[] pdf = PresaleDocRenderEngine.render(tpl, model);
        try (FileOutputStream fos = new FileOutputStream("bug6315-fixed.pdf")) {
            fos.write(pdf);
        }
        System.out.println("PDF written: " + pdf.length + " bytes");

        // 2) 同语义复制渲染（与引擎 flat 替换完全一致的调用）→ DOCX + PNG
        com.aspose.words.Document doc;
        try (InputStream in = RenderBug6315.class.getResourceAsStream(tpl)) {
            doc = new com.aspose.words.Document(in);
        }
        for (Map.Entry<String, String> e : model.getFlat().entrySet()) {
            String key = "${" + e.getKey() + "}";
            String value = e.getValue() == null ? "" : e.getValue();
            doc.getRange().replace(key, value, new com.aspose.words.FindReplaceOptions());
            for (Object s : doc.getChildNodes(com.aspose.words.NodeType.SHAPE, true)) {
                ((com.aspose.words.Shape) s).getRange().replace(key, value, new com.aspose.words.FindReplaceOptions());
            }
        }
        doc.save("bug6315-fixed.docx", com.aspose.words.SaveFormat.DOCX);

        com.aspose.words.ImageSaveOptions opt = new com.aspose.words.ImageSaveOptions(com.aspose.words.SaveFormat.PNG);
        opt.setResolution(150);
        doc.save("bug6315-fixed.png", opt);
        System.out.println("DOCX + PNG written");

        // 3) 占位残留检查（替换后的 Document 全文）
        StringBuilder all = new StringBuilder();
        all.append(doc.getRange().text());
        for (Object s : doc.getChildNodes(com.aspose.words.NodeType.SHAPE, true)) {
            all.append(((com.aspose.words.Shape) s).getRange().text());
        }
        if (all.toString().contains("${")) {
            int i = all.indexOf("${");
            throw new IllegalStateException("PLACEHOLDER RESIDUE: " + all.substring(i, Math.min(i + 60, all.length())));
        }
        System.out.println("NO placeholder residue");
    }
}

import com.aspose.words.Document;
