        data.put("plannedUse", "住宅");
        data.put("saleScope", "2 号楼");
        data.put("totalArea", "690.36");
        data.put("areaDetail", "住宅 690.36㎡");
        data.put("houseCount", "6");
        data.put("houseDetail", "住宅 6 套");
        data.put("bankName", "中国工商银行股份有限公司北京怀柔支行");
        data.put("accountNo", "320211820261011098");
        data.put("remark", "预售有效期：2026-11-06 至 2028-11-06");
        data.put("issueYear", "2026");
        data.put("issueMonth", "11");
        data.put("issueDay", "6");

        registerAspose();
        String tpl = "/templates/presale-permit-template.docx";
        Document doc;
        try (InputStream in = RenderBug6315.class.getResourceAsStream(tpl)) {
            if (in == null) throw new IllegalStateException("模板不存在: " + tpl);
            doc = new Document(in);
        }
        for (Map.Entry<String, String> e : data.entrySet()) {
            String key = "${" + e.getKey() + "}";
            String value = e.getValue() == null ? "" : e.getValue();
            doc.getRange().replace(key, value, new FindReplaceOptions());
            for (Object s : doc.getChildNodes(NodeType.SHAPE, true)) {
                ((Shape) s).getRange().replace(key, value, new FindReplaceOptions());
            }
        }
        ByteArrayOutputStream pdfOut = new ByteArrayOutputStream();
        doc.save(pdfOut, SaveFormat.PDF);
        try (FileOutputStream fos = new FileOutputStream("bug6315-fixed.pdf")) {
            fos.write(pdfOut.toByteArray(), 0, pdfOut.size());
        }
        System.out.println("PDF written: " + pdfOut.size() + " bytes");

        doc.save("bug6315-fixed.docx", SaveFormat.DOCX);
        ImageSaveOptions opt = new ImageSaveOptions(SaveFormat.PNG);
        opt.setResolution(150);
        doc.save("bug6315-fixed.png", opt);
        System.out.println("DOCX + PNG written");

        StringBuilder all = new StringBuilder();
        all.append(doc.getRange().text());
        for (Object s : doc.getChildNodes(NodeType.SHAPE, true)) {
            all.append(((Shape) s).getRange().text());
        }
        String allText = all.toString();
        int i = allText.indexOf("${");
        if (i >= 0) {
            throw new IllegalStateException("PLACEHOLDER RESIDUE: " + allText.substring(i, Math.min(i + 60, allText.length())));
        }
